para.example:
     Visualizzazione delle informazioni sullo zval


<?php
$a = "nuova stringa";
xdebug_debug_zval('a');
?>


     &example.outputs;


a: (refcount=1, is_ref=0)='nuova stringa'

     Incremento del refcount di uno zval


<?php
$a = "nuova stringa";
$b = $a;
xdebug_debug_zval( 'a' );
?>


     &example.outputs;


a: (refcount=2, is_ref=0)='nuova stringa'

     Decremento del refcount di uno zval


<?php
$a = "nuova stringa";
$c = $b = $a;
xdebug_debug_zval( 'a' );
$b = 42;
xdebug_debug_zval( 'a' );
unset( $c );
xdebug_debug_zval( 'a' );
?>


     &example.outputs;


a: (refcount=3, is_ref=0)='nuova stringa'
a: (refcount=2, is_ref=0)='nuova stringa'
a: (refcount=1, is_ref=0)='nuova stringa'

      Creazione di uno zval array


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'meaning' => (refcount=1, is_ref=0)='life',
   'number' => (refcount=1, is_ref=0)=42
)



O graficamente

       Zval per un semplice array

      Aggiunta di un elemento già esistente a un array


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
$a['life'] = $a['meaning'];
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'meaning' => (refcount=2, is_ref=0)='life',
   'number' => (refcount=1, is_ref=0)=42,
   'life' => (refcount=2, is_ref=0)='life'
)



O graficamente

       Zval per un semplice array con un riferimento

      Rimozione di un elemento da un array


<?php
$a = array( 'meaning' => 'life', 'number' => 42 );
$a['life'] = $a['meaning'];
unset( $a['meaning'], $a['number'] );
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=1, is_ref=0)=array (
   'life' => (refcount=1, is_ref=0)='life'
)

      Aggiunta dell'array come elemento di se stesso


<?php
$a = array( 'one' );
$a[] =& $a;
xdebug_debug_zval( 'a' );
?>


      &example.outputs.similar;


a: (refcount=2, is_ref=1)=array (
   0 => (refcount=1, is_ref=0)='one',
   1 => (refcount=2, is_ref=1)=...
)



